def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Find first difference
    min_len = min(len(s_in), len(s_out))

    # Find where they first differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            # Insertion at end
            return ("", s_out[len(s_in):], len(s_in))
        else:
            # Deletion at end
            return (s_in[len(s_out):], "", len(s_out))

    # Check if insertion or replacement
    if len(s_in) < len(s_out):
        # Insertion
        old_sub = ""
        new_sub = s_out[pos:pos+len(s_out)-len(s_in)]
        return (old_sub, new_sub, pos)
    elif len(s_in) > len(s_out):
        # Deletion
        old_sub = s_in[pos:pos+len(s_in)-len(s_out)]
        new_sub = ""
        return (old_sub, new_sub, pos)
    else:
        # Replacement
        old_sub = s_in[pos]
        new_sub = s_out[pos]
        return (old_sub, new_sub, pos)

# Analyze each changed pair
changed = [(0, 'dheby', 'dhieby'), (1, 'kuxek', 'kbduxxbd'), (4, 'ezc', 'iezc')]

for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Pair {idx}: '{s_in}' → '{s_out}'")
    print(f"  Minimal edit: replace '{old_sub}' with '{new_sub}' at position {pos}")
    print()

