inputs = ['dheby', 'kuxek', 'jxu', 'byc', 'ezc']
outputs = ['dhieby', 'kbduxxbd', 'jxu', 'byc', 'iezc']

print("Input -> Output analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")
    if inp != outp:
        # Find where they differ
        for j in range(max(len(inp), len(outp))):
            if j >= len(inp) or j >= len(outp) or inp[j] != outp[j]:
                print(f"  First difference at position {j}")
                if j < len(outp):
                    print(f"  Output has '{outp[j]}' at position {j}")
                if j < len(inp):
                    print(f"  Input has '{inp[j]}' at position {j}")
                break
    print()

